/**
 * Music Playlist Discovery & Section Manifest Ordering
 * Discovers audio files across the three designated folders:
 * 1. Main Birthday Page: public/music/
 * 2. Sad Gallery: public/sad-songs/
 * 3. Happy Gallery: public/happy-songs/
 * 
 * Powered by:
 * - src/config/music-manifest.json (generated by build-time manifest plugin)
 * - src/config/playlist-order.json (authoritative ordering for Main Birthday)
 * - import.meta.glob (fallback discovery)
 */
import musicManifest from '../config/music-manifest.json' with { type: 'json' };
import playlistOrder from '../config/playlist-order.json' with { type: 'json' };
import { BIRTHDAY_CONFIG } from '../config.js';

// Fallback Vite discovery for all folders
const mainAudioModules = typeof import.meta.glob === 'function' ? import.meta.glob(
  [
    '../../public/music/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}',
    '/public/music/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}'
  ],
  { query: '?url', import: 'default', eager: true }
) : {};

const sadAudioModules = typeof import.meta.glob === 'function' ? import.meta.glob(
  [
    '../../public/sad-songs/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}',
    '/public/sad-songs/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}'
  ],
  { query: '?url', import: 'default', eager: true }
) : {};

const happyAudioModules = typeof import.meta.glob === 'function' ? import.meta.glob(
  [
    '../../public/happy-songs/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}',
    '/public/happy-songs/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}'
  ],
  { query: '?url', import: 'default', eager: true }
) : {};

const qnaAudioModules = typeof import.meta.glob === 'function' ? import.meta.glob(
  [
    '../../public/QNA-music/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}',
    '/public/QNA-music/*.{mp3,wav,ogg,m4a,aac,flac,webm,MP3,WAV,OGG,M4A,AAC,FLAC,WEBM}'
  ],
  { query: '?url', import: 'default', eager: true }
) : {};

function normalizeKey(str) {
  if (!str) return '';
  return str
    .toLowerCase()
    .replace(/[\u2010-\u2015\u2212\uFE58\uFE63\uFF0D]/g, '-') // Normalize all dashes/hyphens to ASCII '-'
    .replace(/[\u2018\u2019\u201A\u201B]/g, "'") // Smart quotes
    .replace(/[\u201C\u201D\u201E\u201F]/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

export function extractNumericValue(filename) {
  if (!filename || typeof filename !== 'string') return Infinity;
  const name = filename.split('?')[0].split('/').pop().trim();
  
  // Extract leading filename number e.g. "1.mp3", "2.mp3", "3.wav", "10.mp3", "01.mp3"
  const leading = name.match(/^(\d+)/);
  if (leading) {
    return parseInt(leading[1], 10);
  }

  return Infinity;
}

export function numericSortCompare(a, b) {
  const fileA = typeof a === 'string' ? a : a?.filename || a?.name || '';
  const fileB = typeof b === 'string' ? b : b?.filename || b?.name || '';

  const numA = extractNumericValue(fileA);
  const numB = extractNumericValue(fileB);

  if (numA !== numB) {
    return numA - numB;
  }

  return fileA.localeCompare(fileB, undefined, { numeric: true, sensitivity: 'base' });
}

export function formatTitle(rawFilename, customTitle) {
  if (customTitle && typeof customTitle === 'string' && customTitle.trim() !== '') {
    return customTitle.trim();
  }

  let clean = rawFilename
    .replace(/\.[^/.]+$/, '') // remove extension (.mp3, .m4a, etc.)
    .replace(/\s*[\(\[](Official\s*(Video|Audio|Track|Music|Song)?|Full\s*Song|Audio|Video|Lyric\s*Video)[\)\]]/gi, '')
    .replace(/\b(Full\s*Song|Official\s*Audio|Official\s*Video)\b/gi, '')
    .replace(/\s+[|I]\s+/g, ' - ') // Isolated '|' or 'I' separator
    .replace(/\s+/g, ' ')
    .trim();

  // If filename is purely numeric e.g. "1", "02", "10" -> "Song 1", "Song 2", "Song 10"
  if (/^\d+$/.test(clean)) {
    return `Song ${parseInt(clean, 10)}`;
  }

  // If filename looks like "happy-song1" or "song_01" -> "Happy Song 1"
  if (/^[a-z0-9]+([_-][a-z0-9]+)+$/i.test(clean)) {
    clean = clean
      .replace(/[-_]+/g, ' ')
      .replace(/([a-zA-Z])([0-9])/g, (m, p1, p2) => p1 + ' ' + p2)
      .replace(/([0-9])([a-zA-Z])/g, (m, p1, p2) => p1 + ' ' + p2)
      .replace(/\b\w/g, (c) => c.toUpperCase())
      .trim();
  }

  return clean || rawFilename;
}

function buildPlaylist({
  manifestFiles = [],
  fallbackModules = {},
  folderName = 'music',
  configPlaylist = [],
  configuredOrder = null,
  includeUnlisted = true
}) {
  // 1. If explicitly configured with custom items in config, use that
  if (Array.isArray(configPlaylist) && configPlaylist.length > 0) {
    return configPlaylist.map((item, idx) => {
      const name = item.name || item.title || `Song ${idx + 1}`;
      const src = item.src || item.url || '';
      const filename = src.split('/').pop() || name;
      return {
        id: `${folderName}-config-${idx + 1}`,
        filename,
        title: name,
        name,
        url: src,
        src
      };
    });
  }

  // 2. Index all discovered files from manifest and fallback modules
  const discoveredMap = new Map();

  // Primary: from music-manifest.json
  if (Array.isArray(manifestFiles)) {
    for (const filename of manifestFiles) {
      if (!filename || typeof filename !== 'string') continue;
      const cleanFilename = filename.split('?')[0];
      const key = normalizeKey(cleanFilename);
      if (!discoveredMap.has(key)) {
        discoveredMap.set(key, {
          rawFilename: cleanFilename,
          publicUrl: `/${folderName}/${encodeURI(cleanFilename)}`
        });
      }
    }
  }

  // Fallback: from fallbackModules
  for (const [filepath] of Object.entries(fallbackModules)) {
    const rawFilename = filepath.split('/').pop() || '';
    if (!rawFilename) continue;
    const cleanFilename = rawFilename.split('?')[0];
    const key = normalizeKey(cleanFilename);
    if (!discoveredMap.has(key)) {
      discoveredMap.set(key, {
        rawFilename: cleanFilename,
        publicUrl: `/${folderName}/${encodeURI(cleanFilename)}`
      });
    }
  }

  const allDiscovered = Array.from(discoveredMap.values());

  // Check if any discovered files are named numerically (e.g. 1.mp3, 2.wav, 10.mp3...)
  const hasNumberedFiles = allDiscovered.some(d => extractNumericValue(d.rawFilename) !== Infinity);

  // If there are numbered files, numerical sort is strictly authoritative
  if (hasNumberedFiles) {
    allDiscovered.sort((a, b) => numericSortCompare(a.rawFilename, b.rawFilename));

    // Custom titles lookup if configuredOrder has title overrides
    const titleLookup = new Map();
    if (Array.isArray(configuredOrder)) {
      for (const item of configuredOrder) {
        if (typeof item === 'object' && item?.title) {
          const fn = item.file || item.filename;
          if (fn) titleLookup.set(normalizeKey(fn), item.title);
        }
      }
    }

    return allDiscovered.map((item, idx) => {
      const customTitle = titleLookup.get(normalizeKey(item.rawFilename)) || null;
      return {
        id: `${folderName}-${item.rawFilename}-${idx}`,
        filename: item.rawFilename,
        title: formatTitle(item.rawFilename, customTitle),
        name: formatTitle(item.rawFilename, customTitle),
        url: item.publicUrl,
        src: item.publicUrl
      };
    });
  }

  // If no numbered files exist, follow configuredOrder if matching files exist, then append remaining
  const result = [];
  const processedKeys = new Set();

  if (Array.isArray(configuredOrder) && configuredOrder.length > 0) {
    for (const item of configuredOrder) {
      const filename = typeof item === 'string' ? item : item?.file || item?.filename;
      if (!filename) continue;

      const customTitle = typeof item === 'object' ? item?.title : null;
      const key = normalizeKey(filename);

      const discovered = discoveredMap.get(key);
      if (discovered) {
        result.push({
          id: `${folderName}-${discovered.rawFilename}`,
          filename: discovered.rawFilename,
          title: formatTitle(discovered.rawFilename, customTitle),
          name: formatTitle(discovered.rawFilename, customTitle),
          url: discovered.publicUrl,
          src: discovered.publicUrl
        });
        processedKeys.add(key);
      }
    }
  }

  // Always include any remaining files in natural numeric order
  const remaining = [];
  for (const [key, discovered] of discoveredMap.entries()) {
    if (!processedKeys.has(key)) {
      remaining.push({
        id: `${folderName}-${discovered.rawFilename}`,
        filename: discovered.rawFilename,
        title: formatTitle(discovered.rawFilename, null),
        name: formatTitle(discovered.rawFilename, null),
        url: discovered.publicUrl,
        src: discovered.publicUrl
      });
    }
  }

  remaining.sort((a, b) => numericSortCompare(a.filename, b.filename));
  result.push(...remaining);

  return result;
}

/**
 * Main Birthday Playlist: public/music/
 */
export function getMusicPlaylist() {
  const configOrder = BIRTHDAY_CONFIG?.musicPlayer?.playlistOrder;
  const includeUnlisted = BIRTHDAY_CONFIG?.musicPlayer?.includeUnlistedFiles ?? true;
  return buildPlaylist({
    manifestFiles: musicManifest?.music || [],
    fallbackModules: mainAudioModules,
    folderName: 'music',
    configPlaylist: BIRTHDAY_CONFIG?.musicPlayer?.playlist,
    configuredOrder: Array.isArray(configOrder) && configOrder.length > 0 ? configOrder : playlistOrder,
    includeUnlisted
  });
}

/**
 * Sad Gallery Playlist: public/sad-songs/
 */
export function getSadMusicPlaylist() {
  const configOrder = BIRTHDAY_CONFIG?.sadMusicPlayer?.playlistOrder;
  const includeUnlisted = BIRTHDAY_CONFIG?.sadMusicPlayer?.includeUnlistedFiles ?? true;
  return buildPlaylist({
    manifestFiles: musicManifest?.sad || [],
    fallbackModules: sadAudioModules,
    folderName: 'sad-songs',
    configPlaylist: BIRTHDAY_CONFIG?.sadMusicPlayer?.playlist,
    configuredOrder: configOrder,
    includeUnlisted
  });
}

/**
 * Happy Gallery Playlist: public/happy-songs/
 */
export function getHappyMusicPlaylist() {
  const configOrder = BIRTHDAY_CONFIG?.happyMusicPlayer?.playlistOrder;
  const includeUnlisted = BIRTHDAY_CONFIG?.happyMusicPlayer?.includeUnlistedFiles ?? true;
  return buildPlaylist({
    manifestFiles: musicManifest?.happy || [],
    fallbackModules: happyAudioModules,
    folderName: 'happy-songs',
    configPlaylist: BIRTHDAY_CONFIG?.happyMusicPlayer?.playlist,
    configuredOrder: configOrder,
    includeUnlisted
  });
}

/**
 * Q&A Section Playlist: public/QNA-music/
 */
export function getQnaMusicPlaylist() {
  const configOrder = BIRTHDAY_CONFIG?.qna?.music?.playlistOrder;
  const includeUnlisted = BIRTHDAY_CONFIG?.qna?.music?.includeUnlistedFiles ?? true;
  return buildPlaylist({
    manifestFiles: musicManifest?.qna || [],
    fallbackModules: qnaAudioModules,
    folderName: 'QNA-music',
    configPlaylist: BIRTHDAY_CONFIG?.qna?.music?.playlist,
    configuredOrder: configOrder,
    includeUnlisted
  });
}

/**
 * Universal getter by theme key ('main' | 'sad' | 'happy' | 'qna')
 */
export function getPlaylistForTheme(theme) {
  if (theme === 'sad') return getSadMusicPlaylist();
  if (theme === 'happy') return getHappyMusicPlaylist();
  if (theme === 'qna') return getQnaMusicPlaylist();
  return getMusicPlaylist();
}

export default {
  getMusicPlaylist,
  getSadMusicPlaylist,
  getHappyMusicPlaylist,
  getQnaMusicPlaylist,
  getPlaylistForTheme
};
